  'cost.month.flagged.rule': 'स्कूल को उससे आँका जाता है जो उसकी सीमा में गिना गया, केवल ख़र्च से नहीं। सीमा के पास: सीमा का पाँच में से चार हिस्सा या उससे ज़्यादा गिना जा चुका है। सीमा ने संदेश रोके: पूरी सीमा से कम गिना गया है, पर सीमा आख़िरी बार तय होने के बाद सेंड-गेट ने ऐसा संदेश रोका जो सीमा पार कर देता। सीमा पर या उससे ऊपर: पूरी सीमा गिनी जा चुकी है, और आगे कुछ नहीं भेजा जाता।',
