  'monitoring.invites.line': '{school} ने {email} को {role} के रूप में बुलाया। उस ईमेल का खाता पहले से है, इसलिए कुछ जोड़ा नहीं गया। पूरा पता स्कूल से पूछें, और जोड़ने से पहले खाते के मालिक से पुष्टि करें।',
