  'aud.why.version': 'नियम संस्करण {version}। जाँच चलने के समय, जो आप देख सकते हैं उससे गिना गया।',
  'aud.history.title': 'पिछली जाँचें',
  'aud.history.how': 'जिस दिन जाँच चली, उसकी एक पंक्ति, सबसे नई पहले। बीते दिन की जाँच कभी नहीं बदलती।',
  'aud.history.one': 'रिकॉर्ड में पहली जाँच। आगे जिस दिन भी आप जाँच चलाएँगे, यहाँ एक पंक्ति जुड़ेगी।',
  'aud.history.row': '{applicable} में से {passed} जाँचें ठीक हैं',
  'aud.history.row.none': 'कोई जाँच लागू नहीं हुई',
  'aud.check.class_teacher.title': 'हर कक्षा का एक कक्षा शिक्षक है',
  'aud.check.class_teacher.rule': 'वह कक्षा गिनी जाती है जिसका कोई कक्षा शिक्षक नहीं है, या जिसके कक्षा शिक्षक का खाता बंद है।',
  'aud.check.class_teacher.where': 'स्कूल की कक्षाएँ और स्टाफ़ के खाते।',
  'aud.check.class_teacher.todo.one': '{count} कक्षा का कोई कक्षा शिक्षक नहीं है',
  'aud.check.class_teacher.todo.other': '{count} कक्षाओं का कोई कक्षा शिक्षक नहीं है',
  'aud.check.class_teacher.do': 'कक्षाओं की सूची खोलें और हर उस कक्षा का कक्षा शिक्षक चुनें जिसका कोई नहीं है, या जिसके कक्षा शिक्षक का खाता बंद है।',
  'aud.check.class_teacher.open': 'कक्षा शिक्षक चुनें',
  'aud.check.class_teacher.setup': 'अभी कोई कक्षा नहीं बनी। Students में “Manage classes” से कक्षाएँ जोड़ें।',
  'aud.check.student_guardian.title': 'हर सक्रिय विद्यार्थी का एक अभिभावक है',
  'aud.check.student_guardian.rule': 'वह सक्रिय विद्यार्थी गिना जाता है जिससे कोई अभिभावक जुड़ा नहीं है। किसी दूसरे में मिला दिया गया अभिभावक नहीं गिना जाता।',
