  'aud.check.student_guardian.do': 'हर विद्यार्थी का पेज खोलें और वहाँ अभिभावक जोड़ें।',
  'aud.check.student_guardian.open': 'सक्रिय विद्यार्थी खोलें',
  'aud.check.student_guardian.setup': 'अभी कोई विद्यार्थी सक्रिय नहीं है। पहले विद्यार्थी जोड़ें और उनकी सहमति दर्ज करें।',
  'aud.check.guardian_phone.title': 'हर अभिभावक के नंबर पर WhatsApp पहुँच सकता है',
  'aud.check.guardian_phone.rule': 'वह अभिभावक गिना जाता है जिसका नंबर WhatsApp के काम का नहीं: 6 से 9 से शुरू होने वाला दस अंकों का मोबाइल नंबर, आगे 91 के साथ या बिना, या किसी और देश का नंबर + और उसके कोड के साथ।',
  'aud.check.guardian_phone.where': 'Parents में दिखने वाले अभिभावक।',
