  'aud.check.guardian_phone.open': 'Parents खोलें',
  'aud.check.guardian_phone.setup': 'अभी कोई अभिभावक दर्ज नहीं है। विद्यार्थी के पेज पर अभिभावक जोड़ें।',
  'aud.check.consent.title': 'हर विद्यार्थी की सहमति दर्ज है',
  'aud.check.consent.rule': 'विद्यार्थी तब तक गिना जाता है जब तक वह सहमति की राह देख रहा है: जब तक कोई सत्यापित अभिभावक स्कूल को ज़रूरी सहमतियाँ न दे दे।',
  'aud.check.consent.where': 'विद्यार्थी। डैशबोर्ड पर “सहमति बाकी” वाली वही संख्या।',
  'aud.check.consent.todo.one': '{count} विद्यार्थी की सहमति बाकी है',
