  'aud.check.consent.open': 'राह देख रहे विद्यार्थी खोलें',
  'aud.check.consent.setup': 'अभी कोई विद्यार्थी दर्ज नहीं है। पहले विद्यार्थी जोड़ें।',
  'aud.check.attendance_marked.title': 'पिछले पाँच कामकाजी दिनों में हर दिन हाज़िरी लगी',
  'aud.check.attendance_marked.rule': 'आज से पहले के सबसे नए पाँच कामकाजी दिन देखे जाते हैं, आपके कामकाजी दिनों और छुट्टियों के हिसाब से। वह दिन गिना जाता है जब विद्यार्थियों वाली किसी कक्षा की हाज़िरी नहीं लगी।',
