  'ew.open.empty.partial.do': 'पिछली जाँच जिन बच्चों को जाँच सकी, उनमें किसी को देखने का कारण नहीं मिला। देखे गए {students} विद्यार्थियों में से {used} की हाज़िरी इस्तेमाल हो सकी: बाक़ी के पिछले {days} दिनों में {min} से कम दिन हाज़िरी लगी है, इसलिए उनकी हाज़िरी के बारे में वह कुछ नहीं कहती। हर स्कूली दिन हाज़िरी लगाते रहें, फिर “अभी जाँचें” दबाएँ।',
