  'moduleOff.curriculum-gap': '“पाठ्यक्रम में छूटे हिस्से” मेनू से हट जाएगा, शिक्षकों के मेनू से भी, और इसका पेज नहीं खुलेगा। यह कुछ जमा नहीं करता: पाठ्यक्रम के नक्शे, पाठ और परीक्षा पेपर बने रहेंगे।',
  'tour.curriculum-gap.1.title': 'कक्षा और विषय चुनें',
  'tour.curriculum-gap.1.text': 'उसके पाठ्यक्रम के नक्शे की हर इकाई एक बार, नक्शे के क्रम में दिखती है। नक्शा न हो तो पेज बताता है कि यह अभी तैयार नहीं है।',
  'tour.curriculum-gap.2.title': 'हर इकाई की एक स्थिति',
  'tour.curriculum-gap.2.text': 'पढ़ाई और जाँची गई, पढ़ाई पर जाँची नहीं गई, पढ़ाने से पहले जाँची गई, छूट गई, या अभी नहीं पढ़ाई गई, उन दिनों के साथ जिन पर यह टिकी है।',
