  'cg.how.taught-assessed': 'पढ़ाई और जाँची गई: पढ़ाई गई, और ऐसे पेपर में है जिसकी तारीख़ पहले पाठ के दिन या उसके बाद की है, या जिसकी अभी तारीख़ नहीं है।',
