  // p6-9e begin
  // Learning Genome v1 (docs/27 row 9e, C217): one child's own exams, homework and Pulse replies, for staff only.
  'moduleOff.learning-genome': '“लर्निंग जीनोम” मेनू से हट जाता है और कोई भी बच्चे का जीनोम नहीं खोल सकता। यह कुछ सहेजता नहीं, इसलिए कुछ नहीं खोता: अंक, होमवर्क और जवाब अपनी जगह रहते हैं।',
  'tour.learning-genome.1.title': 'कक्षा चुनें, फिर बच्चा',
  'tour.learning-genome.1.text': 'शिक्षक अपनी कक्षाओं के बच्चे देखते हैं। ऑफ़िस और एकेडमिक कोऑर्डिनेटर हर कक्षा देखते हैं।',
  'tour.learning-genome.2.title': 'तुलना सिर्फ़ अपने आप से',
  'tour.learning-genome.2.text': 'मज़बूतियाँ और कमियाँ बच्चे को उसकी अपनी पिछली परीक्षा, अपने कुल और अपने जवाबों से मिलाती हैं। कभी किसी दूसरे बच्चे से नहीं।',
  'tour.learning-genome.3.title': 'हर संख्या बताती है कि कहाँ से आई',
  'tour.learning-genome.3.text': 'प्रतिशत अपने अंक दिखाता है, होमवर्क अपनी जाँच, अध्याय वे जवाब जो वह गिनता है, और हर नियम Settings में तय रेखा।',
  'set.learning-genome.trend_points.label': 'कोई विषय कम से कम इतने अंक ऊपर या नीचे गया',
  'set.learning-genome.trend_points.help': 'कोई विषय मज़बूती है जब बच्चे का प्रतिशत उसी विषय की उसकी अपनी पिछली परीक्षा से कम से कम इतने अंक बढ़ा, और कमी जब इतना ही घटा, 1 से 50 तक।',
  'set.learning-genome.spread_points.label': 'कोई विषय अपने कुल से कम से कम इतने अंक ऊपर या नीचे',
  'set.learning-genome.spread_points.help': 'बच्चे की सबसे नई परीक्षा में, जिसमें दो या ज़्यादा विषय हों, जो विषय उस परीक्षा के उसके अपने कुल से इतने अंक ऊपर है वह मज़बूती है, और इतना ही नीचे कमी, 1 से 50 तक।',
  'set.learning-genome.needs_help_replies.label': 'कम से कम इतने “मदद चाहिए” जवाबों वाला अध्याय',
  'set.learning-genome.needs_help_replies.help': 'कोई अध्याय कमी है जब बच्चे के अभिभावकों ने देखे गए दिनों में उसके पढ़ाए गए पाठों के Daily Pulse पर कम से कम इतनी बार “मदद चाहिए” कहा, 1 से 20 तक।',
  'set.learning-genome.understood_replies.label': 'कम से कम इतने “समझ गए” जवाबों वाला अध्याय',
  'set.learning-genome.understood_replies.help': 'कोई अध्याय मज़बूती है जब अभिभावकों ने कम से कम इतनी बार “समझ गए” कहा और कभी “मदद चाहिए” नहीं, 1 से 20 तक।',
  'set.learning-genome.homework_done_below.label': 'हर 100 में से इतने से कम होमवर्क किए',
  'set.learning-genome.homework_done_below.help': 'किसी विषय में होमवर्क कमी है जब बच्चे ने देखे गए दिनों में जाँचे गए हर 100 होमवर्क में से इतने से कम किए, 1 से 100 तक।',
  'set.learning-genome.homework_min_checked.label': 'सिर्फ़ तब जब कम से कम इतने होमवर्क जाँचे गए',
  'set.learning-genome.homework_min_checked.help': 'होमवर्क तब तक नहीं गिना जाता जब तक उस विषय में बच्चे के कम से कम इतने होमवर्क जाँचे न गए हों, 1 से 50 तक। इससे कम में एक छूटा होमवर्क असल से बड़ा दिखेगा।',
  'set.learning-genome.window_days.label': 'होमवर्क और जवाब इतने दिन पीछे तक',
  'set.learning-genome.window_days.help': 'होमवर्क और Daily Pulse के जवाब कितने दिन पीछे तक गिने जाते हैं, आज समेत, 7 से 366 तक। परीक्षाएँ पहली प्रकाशित परीक्षा से गिनी जाती हैं।',
